from lib import *
P('base-area-353','Base Area 353', in_='x') if False else None
D='vietnam-hanoi'; OP=['vietnam-operations']
E('tet-letter','1969','1969, early','Hồ Chí Minh\'s Tết letter to the people and fighters of the whole country: the strategic direction of the war in the new stage, "Đánh cho Mỹ cút, đánh cho ngụy nhào" (strike so the Americans go, strike so the puppets fall).','163–64',at='before 1969-01',ntags=['name:ho-chi-minh'],names=['Hồ Chí Minh'],check='the day; the history says "đầu năm 1969, nhân dịp Tết Nguyên đán".',lw='Hồ Chí Minh\'s Tết letter, the direction of the war')
E('testament-study','1969-09','Sept., after the 2d','After Hồ Chí Minh\'s death the Politburo directs a round of political study in the Party and the army: learn and follow his testament; the study of the Central Committee\'s 18th plenum follows.','170, 193',at='after 1969-09-02',place='hanoi',ntags=['name:ho-chi-minh'],names=['Hồ Chí Minh'],see='cal.1969-09-02.vietnam-hanoi',check='the day; the history gives only that it followed his death.',lw='Politburo directs study of Hồ Chí Minh\'s testament')
E('army-study','1969-06','June','The whole army begins a round of political study on the situation and new tasks, after the class of cadres in Hanoi; units hold emulation congresses on the resolve to beat the American invaders, and the regions, services and arms in the North sum up four years of beating the air war.','193',at=None,see='cal.1969-05.vietnam-hanoi',check='the days; the history gives the month.',ok=['ok:fields-place'], lw='Army political study on the situation and new tasks')
E('army-reorg','1969','1969, mid','The Central Military Party Committee orders the army to tighten organization, raise quality and trim the standing forces. The 377th and 375th Air Defense Divisions, the 269th Bridge and Ferry Engineer Regiment and the 268th and 278th SAM Regiments are dissolved to reinforce the guard of key places, the fighting in southern Military Region 4 and Route 559; the Navy and the northern regions and schools cut staff and send over 13,000 to the fighting units. Group 500, from the south bank of the Gianh to the 17th parallel, with seven truck, eight engineer and two 37 mm battalions, a pipeline battalion and its stations, is folded into Group 559.','194–95, 212',at='before 1969-05',vis=True,also=OP,check='the day; the history says "từ mùa hè năm 1969" for the order (p. 194) and "giữa năm 1969" for Group 500 (p. 212).',lw='Central Military Party Committee trims forces, dissolves Group 500')
E('route559-early','1969','1969, early','Route 559. Group 559, with Group 500, clears the main pass sectors on Routes 12 and 20 and opens branches 20c, 20d and bypasses; the General Staff adds engineers to open Route 18, a new crossing toward Route 9; Quảng Bình mobilizes 20,000 laborers to build Route 10 to join Routes 18 and 16; river stretches are used to float cargo down.','211',at='before 1969-01',also=OP,check='the days; the history gives "những tháng đầu của năm 1969".',lw='Route 559 passes cleared, new crossings opened')
E('pipeline','1969','1969','Fuel pipeline across the Trường Sơn. After a survey from mid-1968, Construction Site 18 lays the first stretch, 42 km through Vinh, Nam Đàn and Linh Cảm, the center of a line run north and south. By 1971 nearly 1,000 km is laid and working, in two branches, one over the Cổng Trời pass along Route 12 into Laos, one across the Gianh by Routes 10 and 18 to north of Route 9.','216–17',also=OP,vis=True,check='the day; the history gives the three years 1969–71.',ok=['ok:fields-place'], lw='Trường Sơn fuel pipeline begun')
E('route559-1969','1969','1969','Route 559 carries 170,000 tons of cargo into the South, 29 percent more than in 1968: hundreds of thousands of rifles, B-40 and B-41 rockets and recoilless guns, hundreds of millions of rounds, thousands of radios. Over 80,000 troops march south over the Trường Sơn to the fronts. In the dry season of 1968–69 the tankers had brought in only about 90 tons of fuel against a need of 500.','218–19',also=OP,vis=True,see='north-aid',check='the day; the history gives the year and its own tonnages, which differ from the 52,424 tons of p. 93.',lw='Route 559 carries 170,000 tons in 1969')
E('nixon-0514','1969-05-14','May 14','Nixon\'s eight-point address on Vietnam: American troops to leave on conditions, both sides, the United States and the DRV, to de-escalate and withdraw together from the South, the Saigon government to stay as it is. The history sets it against the Front\'s ten points.','225',th='vietnam-paris',also=[D],polity='us',ntags=['name:nixon-richard-m'],names=['Nixon'],see='cal.1969-05-08.vietnam-hanoi-2',tocheck='Nixon, *Public Papers* (1969), the address of May 14.',check='the points; the history gives no detail and the American record should be read.',ok=['ok:fields-place'], lw='Nixon\'s eight-point address on Vietnam')
E('thieu-0711','1969-07-11','July 11','Thiệu\'s six-point message: American withdrawal on conditions, mutual withdrawal of the two sides from the South, and the Saigon government kept as it is.','225',th='vietnam-paris',also=[D],polity='rvn',ntags=['name:nguyen-van-thieu'],names=['Thiệu'],see='cal.1969-05-08.vietnam-hanoi-2',check='the points and the day; the history gives only the date and the three conditions.',ok=['ok:fields-place'], lw='Thiệu\'s six-point message')
E('us-0608','1969-06-08','June 8','The American President announces the withdrawal of 25,000 American troops from South Vietnam.','44',th='vietnam-force-levels',polity='us',check='the place and the speaker; the history says "Tổng thống Mỹ".',lw='25,000 American troops to be withdrawn')
E('us-0707','1969-07-07','July 7','A battalion of the American 9th Infantry Division, the first unit to leave, withdraws from Vietnam.','44',th='vietnam-force-levels',polity='us',lw='First American battalion withdrawn')
E('us-0916','1969-09-16','Sept. 16','Nixon announces a second withdrawal, 35,000 American troops.','44',th='vietnam-force-levels',polity='us',ntags=['name:nixon-richard-m'],names=['Nixon'],lw='Second American withdrawal, 35,000')
E('us-0930','1969-09-30','Sept. 30','The American President announces an order to withdraw 6,000 American troops from Thailand.','44',th='vietnam-force-levels',also=['thailand'] if False else [],polity='us',check='the date of departure; the history says October 1970, the month the order takes effect.',lw='Order to withdraw 6,000 troops from Thailand')
E('nixon-1103','1969-11-03','Nov. 3','Nixon\'s statement on Vietnam; the history draws his account of Vietnamization from it.','29 and n. 1',th='vietnam',polity='us',ntags=['name:nixon-richard-m'],names=['Nixon'],tocheck='Nixon, *Public Papers* (1969), the address of Nov. 3.',check='the form; the history gives the day and quotes in translation.',lw='Nixon\'s statement on Vietnam, Nov. 3')
C('cal.1969-07-25.vietnam','15–16, 29 and n.','the Guam address of July 1969 in three points: the United States to keep its treaty commitments; a nuclear shield against a nuclear power; in other aggression, aid on request, the threatened state to supply the manpower for its own defense; the history names it the Nixon Doctrine and has Laird, Jan. 14, 1970, call Vietnamization its first test','B')
E('pacif-plan','1969','1969, early','Nixon puts a three-phase pacification and development plan into force in the South. Phase 1, building pacification, runs from the start of 1969 to June 1970; phase 2, special pacification, July 1970–June 1971; phase 3, community self-defense and rural development, from July 1971. The 1969 target: kill 30 percent of the 98,763 local revolutionary cadres the enemy has found; by mid-1970, secure 60 percent of the land. The history dates "accelerated pacification" Nov. 1968–June 1969 and the "rural development" phase July 1969–June 1970.','52, 74–75 and n. 1',th='vietnam-pacification',also=[D],polity='us',at='before 1969-01',ntags=['name:nixon-richard-m'],names=['Nixon'],check='the plan\'s day and its phases; the history\'s two datings of the first stages differ (p. 52 against p. 74 n. 1).',lw='Nixon\'s three-phase pacification plan')
E('samakhi','1969-04','Apr., late–June','Laos. Vang Pao\'s special forces and the right-wing army, directed by the Americans, open three operations, Samakkhi (Solidarity) I, II and III, to take Xieng Khoảng town and the ground round the Plain of Jars. The Lao People\'s Liberation Army\'s 1st and 701st Battalions, with the local forces and guerrillas of Mường Khun, stop and wear them down, and they fall back to Sam Thong and Long Tieng.','239',th='laos',also=[D],at='before 1969-04-21',polity='laos',tags=['polity:pathet-lao'],ntags=['name:vang-pao'],names=['Vang Pao'],check='the days; the history gives "cuối tháng 4-1969 đến tháng 6-1969".',place='plain-of-jars', lw='Samakkhi I, II, III on the Plain of Jars')
E('musui-end','1969-06-28','June 28–July 1','Mường Sủi. The Vietnamese and Lao forces take all of Mường Sủi and pursue the remnants to the Salaphu Khun junction, threatening Sam Thong and Long Tieng; the campaign ends. By their count the long-held defenses are broken. Khamtay Siphandone says it shows the Lao–Vietnamese forces can beat the "intensified special war"; UPI, June 28, calls it the Americans\' costliest battle in Laos since the start of 1969.','240 and n. 1',th='laos',also=[D],polity='laos',tags=['polity:pathet-lao'],see='cal.1969-06-23.vietnam-hanoi',check='the words; the history renders Khamtay and UPI in Vietnamese.',lw='Mường Sủi taken; the campaign ends')
E('koukiet','1969-07-31','July 31','Laos. Under cover of American air and artillery, a mixed force from Sam Thong–Long Tieng and Vang Vieng, Vang Pao\'s men, the right-wing army and 5,000 Thais, 18 battalions and 52 companies of special forces in all, opens Kou Kiet and drives into the center of the Plain of Jars. The rains have flooded the defenders\' works; the advance is fast, with villages burned.','241–42 and n. 1',th='laos',also=[D],polity='laos',tags=['polity:pathet-lao','polity:thailand'],ntags=['name:vang-pao'],names=['Vang Pao'],bnd=None,check='the day of the opening; the history gives "cuối tháng 7-1969" and, for the attack, July 31.',place='plain-of-jars', ok=['ok:fields-place'], lw='Kou Kiet opens on the Plain of Jars')
E('plain-sep','1969-09','Sept.','Laos. By September the Americans and their allies hold the Plain of Jars and stand at the gates near the Vietnamese border, Bản Ban and Nong Het. At the end of the month the Vietnamese troops are ordered back to rest and refit, leaving a little over a battalion with the Lao to hold a springboard; the Lao and Vietnamese decide on a counteroffensive, Campaign 139.','242–43',th='laos',also=[D],polity='laos',tags=['polity:pathet-lao'],see='cal.1969-10-25.vietnam-hanoi',check='the days; the history gives the month and "cuối tháng 9-1969".',place='plain-of-jars', ok=['ok:fields-at'], lw='The Plain of Jars lost; Campaign 139 decided')
E('base353','1969-02','Feb., mid','American B-52s are ordered to strike Base Area 353 in Cambodia, the Parrot\'s Beak and the Fishhook, where Abrams believes the Central Office for South Vietnam sits; Nixon agrees to Abrams\'s proposal. The history takes the second quotation from Joseph Amter.','247–48 and n. 1',th='vietnam-operations',also=[D],polity='us',at='before 1969-02-10',ntags=['name:nixon-richard-m'],names=['Nixon'],check='the day; the history says "giữa tháng 2-1969" and the strikes follow the early spring offensive.',lw='B-52 strikes ordered on Base Area 353')
E('cambodia-us','1969-02','Feb.','Cambodia and the United States restore diplomatic relations at the level of ambassador, after nearly four years. The history says the American embassy in Phnom Penh and the CIA then encouraged Lon Nol.','249',th='vietnam',polity='us',check='the month; the history says Feb. 1969.',ok=['ok:fields-place'], lw='Cambodia and the United States restore relations')
V('uminh-0926','B','from September 1969 the Saigon 21st Division, Marine Brigade B, four Ranger battalions, river groups and air support open the first sweep to take U Minh, and fail','VI, 264')
E('prg-recog','1969-06','June','Twenty-two socialist and democratic states recognize the Provisional Revolutionary Government and open diplomatic relations with it soon after its formation. By 1971 it has relations with 26.','96, 226, 236',th='vietnam-paris',also=[D],see='cal.1969-06-06.vietnam-hanoi',check='the days; the history says "ngay sau khi thành lập", and gives "hơn 20" at p. 226 and 26 for 1971.',ok=['ok:fields-at'], lw='Twenty-two states recognize the PRG')
